CREATE DATABASE IF NOT EXISTS ar_tourism CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ar_tourism;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('admin') NOT NULL DEFAULT 'admin', status ENUM('active','inactive') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, slug VARCHAR(140) NOT NULL UNIQUE, description TEXT, status ENUM('active','inactive') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE destinations (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id INT UNSIGNED NULL, name VARCHAR(180) NOT NULL, slug VARCHAR(200) NOT NULL UNIQUE, short_description VARCHAR(500), description TEXT, cover_image VARCHAR(255), location VARCHAR(180), latitude DECIMAL(10,7), longitude DECIMAL(10,7), maps_url VARCHAR(500), status ENUM('active','inactive') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(status), FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL);
CREATE TABLE attractions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, destination_id INT UNSIGNED NOT NULL, category_id INT UNSIGNED NULL, name VARCHAR(180) NOT NULL, slug VARCHAR(200) NOT NULL UNIQUE, short_description VARCHAR(500), description TEXT, main_image VARCHAR(255), youtube_url VARCHAR(500), website_url VARCHAR(500), maps_url VARCHAR(500), latitude DECIMAL(10,7), longitude DECIMAL(10,7), opening_hours VARCHAR(255), entry_information VARCHAR(255), display_order INT DEFAULT 0, status ENUM('active','inactive') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(destination_id,status), FOREIGN KEY(destination_id) REFERENCES destinations(id) ON DELETE CASCADE, FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL);
CREATE TABLE attraction_images (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, attraction_id INT UNSIGNED NOT NULL, image_path VARCHAR(255) NOT NULL, caption VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(attraction_id) REFERENCES attractions(id) ON DELETE CASCADE);
CREATE TABLE ar_posters (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(180) NOT NULL, description TEXT, poster_image VARCHAR(255) NOT NULL, target_file VARCHAR(255), target_status ENUM('NOT_COMPILED','READY') NOT NULL DEFAULT 'NOT_COMPILED', target_compiled_at DATETIME NULL, status ENUM('active','inactive') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE ar_hotspots (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, poster_id INT UNSIGNED NOT NULL, attraction_id INT UNSIGNED NULL, label VARCHAR(120) NOT NULL, x DECIMAL(7,5) NOT NULL, y DECIMAL(7,5) NOT NULL, width DECIMAL(7,5) NOT NULL DEFAULT .2, height DECIMAL(7,5) NOT NULL DEFAULT .12, z_index INT DEFAULT 1, video_url VARCHAR(500), content_type ENUM('card','video','link') NOT NULL DEFAULT 'card', FOREIGN KEY(poster_id) REFERENCES ar_posters(id) ON DELETE CASCADE, FOREIGN KEY(attraction_id) REFERENCES attractions(id) ON DELETE SET NULL);
CREATE TABLE activity_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL, action VARCHAR(120) NOT NULL, description TEXT, ip_address VARCHAR(45), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(created_at), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value TEXT);
